WITH exploded AS (SELECT id, plan, effective_from, EXPLODE_OUTER(discounts) AS tier_value FROM price_tiers), scored AS (SELECT *, RANK() OVER w_recent tier_value_rank, COUNT(tier_value) OVER w_grp plan_count_tier_value, DENSE_RANK() OVER (PARTITION BY plan ORDER BY tier_value NULLS LAST) tier_value_dense_rank FROM exploded WINDOW w_recent AS (ORDER BY tier_value DESC), w_grp AS (PARTITION BY plan)), kept_keys AS (SELECT id, plan FROM scored EXCEPT DISTINCT SELECT id, plan FROM price_tiers WHERE currency <> 'THB'), reconciled AS (SELECT s.* FROM scored s INNER JOIN kept_keys k ON s.id = k.id AND s.plan = k.plan), with_windows AS (SELECT plan, effective_from, tier_value, tier_value_rank, tier_value_dense_rank, DENSE_RANK() OVER (ORDER BY tier_value_dense_rank DESC NULLS FIRST) tier_value_dense_rank_dense_rank, AVG(tier_value_rank) OVER (PARTITION BY plan) plan_avg_tier_value_rank FROM reconciled), filtered AS (SELECT plan, tier_value, tier_value_rank, tier_value_dense_rank, tier_value_dense_rank_dense_rank, CASE WHEN plan_avg_tier_value_rank >= 7 THEN 'High' WHEN plan_avg_tier_value_rank >= 5 THEN 'Medium' ELSE 'Low' END plan_avg_tier_value_rank_level, ROUND(tier_value_dense_rank_dense_rank / plan_avg_tier_value_rank, 2) tier_value_dense_rank_dense_rank_per_plan_avg_tier_value_rank FROM with_windows WHERE tier_value_rank = 8) SELECT plan, CASE WHEN tier_value_dense_rank_dense_rank_per_plan_avg_tier_value_rank >= 71 THEN 'LARGE' ELSE 'SMALL' END AS tier_value_dense_rank_dense_rank_per_plan_avg_tier_value_rank_tier, PERCENTILE_APPROX(tier_value_dense_rank_dense_rank, 0.95) AS tier_value_dense_rank_dense_rank_p95, SIZE(COLLECT_SET(plan)) AS num_plans, SUM(CASE WHEN plan = 'starter' THEN tier_value_dense_rank ELSE 0 END) AS starter_tier_value_dense_rank, GROUPING(plan) AS grouping_id FROM filtered GROUP BY GROUPING SETS ((plan, CASE WHEN tier_value_dense_rank_dense_rank_per_plan_avg_tier_value_rank >= 71 THEN 'LARGE' ELSE 'SMALL' END), (plan), ()) ORDER BY num_plans NULLS LAST
